_DISCLAIMER = ("CodeBench's own workloads of the kinds SPEC CPU 2017 and SPEC CPU 2026 run — "
               "not SPEC, and not SPEC results. SPEC® and SPEC CPU® are trademarks of the "
               "Standard Performance Evaluation Corporation.")


def _check(wid, size, res):
    want = EXPECTED.get((wid, size))
    if want is None:
        return None
    kind, expect = want
    if kind == "c":
        return res.checksum == expect
    return abs(res.value - expect) <= 1e-6 * max(abs(expect), 1e-300)


def spec(sh, argv):
    with _Boost():
        return _spec(sh, argv)


def _spec(sh, argv):
    """spec — CodeBench's CPU suites, of the kinds of work SPEC CPU runs.

    Usage:
      spec 2017|2026 [int|fp|all] [--rate [N] | --speed] [--quick | --large]
                     [--iterations N] [--only a,b,…] [--json [path]]
      spec --list    the workloads and what each stands for

    --speed (the default) runs one copy of each workload; --rate runs N
    copies at once (all cores by default) and reports throughput. Each
    workload's answer is checked; a time is the median of --iterations
    runs (1, or 3 with --iterations 3). Ratios are against a Mac mini M4
    (Mac16,10) running this app: 10.0 there, per copy.
    """
    BOLD, DIM, RED, GRN, YLW, CYN, WHT, RESET = _colors()
    w = sys.stdout.write
    lib = native()
    if lib is None:
        print(f"{RED}spec:{RESET} this build has no native benchmark workloads.")
        return
    if "--list" in argv or not argv:
        if not argv:
            print((spec.__doc__ or "").strip().split("\n\n", 1)[1] if spec.__doc__ else "")
        for year in ("2017", "2026"):
            for kind in ("int", "fp"):
                w(f"\n  {BOLD}{year} {kind}{RESET}\n")
                for num, wid, what, like in SUITES[year][kind]:
                    w(f"    {num}.{wid:<12}{what:<40}{DIM}like {like}{RESET}\n")
        w(f"\n  {DIM}{_DISCLAIMER}{RESET}\n\n")
        return

    year = next((a for a in argv if a in SUITES), "2017")
    kinds = [k for k in ("int", "fp") if k in argv] or ["int", "fp"]
    size = 1 if "--quick" in argv else 3 if "--large" in argv else 2
    rate = "--rate" in argv
    copies = 1
    if rate:
        n = _option(argv, "--rate")
        copies = int(n) if n and n.isdigit() else (os.cpu_count() or 1)
    iterations = max(1, int(_option(argv, "--iterations", "1") or 1))
    only = set(filter(None, (_option(argv, "--only", "") or "").split(",")))
    known = {lib.cb_spec_id(i).decode() for i in range(lib.cb_spec_count())}

    product, chip = device_line()
    info = cpu_info()
    cols = _columns()
    wide = cols >= 104                    # room for the kind-of-work column
    rule = "─" * (min(cols, 104) - 2)
    import textwrap

    def para(text):
        return "".join(f"  {line}\n" for line in textwrap.wrap(text, max(40, cols - 4)))
    metric = f"rate, {copies} copies" if rate else "speed, 1 copy"
    sizes = {1: "quick", 2: "standard", 3: "large"}
    w(f"\n{BOLD}CodeBench CPU suite {year}{RESET}  {DIM}({metric} · {sizes[size]} size · "
      f"{iterations} iteration{'s' if iterations > 1 else ''}){RESET}\n")
    w(f"{DIM}{para(_DISCLAIMER)}{RESET}")
    w(f"{DIM}{rule}{RESET}\n")
    system = (f"{product} · {chip} · {info['cores']} cores"
              + (f" ({info['p_cores']}P + {info['e_cores']}E)" if "p_cores" in info else "")
              + f" · {info.get('memory', 0) / (1 << 30):.0f} GB · {platform.system()} {platform.release()}")
    w(para("System   " + system))
    w(f"{DIM}{rule}{RESET}\n")

    report = {"suite": year, "metric": "rate" if rate else "speed", "copies": copies, "size": size,
              "iterations": iterations, "device": product, "chip": chip, "cpu": info,
              "when": time.strftime("%Y-%m-%d %H:%M:%S"), "disclaimer": _DISCLAIMER, "workloads": []}
    started = time.perf_counter()
    ratios = {"int": [], "fp": []}
    failures = 0
    try:
        for kind in kinds:
            rows = [r for r in SUITES[year][kind] if not only or r[1] in only]
            w(f"  {BOLD}{'Integer' if kind == 'int' else 'Floating point'}{RESET}\n")
            w(f"  {DIM}{'workload':<17}" + (f"{'kind of work':<38}" if wide else "")
              + f"{'time':>9}{'ratio':>8}  {'throughput':>26}  check{RESET}\n")
            for i, (num, wid, what, like) in enumerate(rows, 1):
                if wid not in known:
                    w(f"  {num}.{wid:<12}{DIM}not in this build{RESET}\n")
                    continue
                times, res, ok = [], None, True
                for it in range(iterations):
                    _status(f"{YLW}running{RESET} {num}.{wid} ({i} of {len(rows)}"
                            + (f", iteration {it + 1}" if iterations > 1 else "") + ")…")
                    if copies == 1:
                        dt, res = run_workload(lib, wid, size)
                        results = [(dt, res)]
                    else:
                        dt, results = run_copies(lib, wid, size, copies)
                        res = results[0][1]
                    if dt is None or any(r is None or r[0] is None for r in results):
                        ok = False
                        break
                    for _, r in results:
                        if _check(wid, size, r) is False:
                            ok = False
                    times.append(dt)
                w("\r\033[K")
                if not times:
                    failures += 1
                    w(f"  {num}.{wid:<12}" + (f"{what[:36]:<38}" if wide else "")
                      + f"{RED}{'failed':>9}{RESET}\n")
                    continue
                t = sorted(times)[len(times) // 2]
                ref = REFERENCE.get((wid, size))
                # 10 a copy on the reference Mac, as the summary says.
                ratio = 10.0 * copies * ref / t if ref else None
                if ratio and ok:
                    ratios[kind].append(ratio)
                if not ok:
                    failures += 1
                per_s = res.work * copies / t if res.work else 0
                unit = (res.unit or b"").decode()
                thr = _si(per_s) + f" {unit}/s"
                verdict = (f"{GRN}✓{RESET}" if ok and _check(wid, size, res) else
                           f"{DIM}–{RESET}" if ok else f"{RED}✗ answer differs{RESET}")
                w(f"  {num}.{wid:<12}" + (f"{what[:36]:<38}" if wide else "")
                  + f"{WHT}{t:>8.2f}s{RESET}{(f'{ratio:8.2f}' if ratio else '       –')}"
                  f"  {DIM}{thr:>26}{RESET}  {verdict}\n")
                sys.stdout.flush()
                report["workloads"].append({
                    "number": num, "id": wid, "kind": kind, "work_kind": what, "like": like,
                    "seconds": times, "median_s": t, "ratio": ratio, "valid": ok,
                    "checksum": f"{res.checksum:016x}", "value": res.value,
                    "work": res.work, "unit": unit})
            w("\n")
    except KeyboardInterrupt:
        w(f"\r\033[K  {YLW}stopped{RESET} — the summary covers the workloads that finished.\n\n")

    elapsed = time.perf_counter() - started
    w(f"{DIM}{rule}{RESET}\n")
    label = "rate" if rate else "speed"
    summary = {}
    for kind in kinds:
        g = _geomean(ratios[kind])
        if g:
            summary[kind] = g
            name = "Integer" if kind == "int" else "Floating point"
            w(f"  {BOLD}{name:<16}{RESET}{GRN}{BOLD}{g:8.2f}{RESET}  {DIM}geometric mean of "
              f"{len(ratios[kind])} {label} ratios{RESET}\n")
    if len(summary) == 2:
        overall = _geomean(list(summary.values()))
        w(f"  {BOLD}{'Overall':<16}{RESET}{GRN}{BOLD}{overall:8.2f}{RESET}  {DIM}("
          + ("10 a copy run at a Mac mini M4 performance core's speed" if rate
             else "a Mac mini M4 performance core = 10.0") + f"){RESET}\n")
        summary["overall"] = overall
    if failures:
        w(f"  {RED}{failures} workload{'s' if failures > 1 else ''} failed or gave a different "
          f"answer — those are left out of the means.{RESET}\n")
    w(f"  {DIM}{elapsed:.1f} s in all{RESET}\n")
    report["summary"] = summary
    report["elapsed_s"] = elapsed
    if "--json" in argv or any(a.startswith("--json=") for a in argv):
        path = _save_json(f"suite-{year}", report, _option(argv, "--json"))
        w(f"  {DIM}saved {path}{RESET}\n")
    w("\n")
    sys.stdout.flush()


# The help text lives on the functions that do the work.
cpuz.__doc__ = _cpuz.__doc__
gpuz.__doc__ = _gpuz.__doc__
spec.__doc__ = _spec.__doc__
